package data_structures.linear;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class SkipList {
public static class ListImpl<T> implements Iterable<T>{private static class Node<T>{final T value;final List<Node<T>> next;Node(T v,int n){value=v;next=new ArrayList<>(Collections.nCopies(n,null));}}private final Comparator<T> compare;private final int maxLevel;private final double probability;private final Node<T> head;private int level=1,length;public ListImpl(){this(shared.Compare::defaultCompare,32,.5);}public ListImpl(Comparator<T> compare){this(compare,32,.5);}public ListImpl(Comparator<T> c,int max,double p){if(max<1||p<0||p>=1)throw new IllegalArgumentException();compare=c;maxLevel=max;probability=p;head=new Node<>(null,max);}public int size(){return length;}private List<Node<T>> predecessors(T v){List<Node<T>> u=new ArrayList<>(Collections.nCopies(maxLevel,head));Node<T> n=head;for(int i=level-1;i>=0;i--){Node<T> next=n.next.get(i);while(next!=null&&compare.compare(next.value,v)<0){n=next;next=n.next.get(i);}u.set(i,n);}return u;}public boolean has(T v){Node<T> n=predecessors(v).get(0).next.get(0);return n!=null&&compare.compare(n.value,v)==0;}public boolean insert(T v){List<Node<T>> u=predecessors(v);Node<T> n=u.get(0).next.get(0);if(n!=null&&compare.compare(n.value,v)==0)return false;int l=1;while(l<maxLevel&&Math.random()<probability)l++;if(l>level){for(int i=level;i<l;i++)u.set(i,head);level=l;}n=new Node<>(v,l);for(int i=0;i<l;i++){n.next.set(i,u.get(i).next.get(i));u.get(i).next.set(i,n);}length++;return true;}public boolean delete(T v){List<Node<T>> u=predecessors(v);Node<T> n=u.get(0).next.get(0);if(n==null||compare.compare(n.value,v)!=0)return false;for(int i=0;i<level;i++){if(u.get(i).next.get(i)!=n)break;u.get(i).next.set(i,n.next.get(i));}while(level>1&&head.next.get(level-1)==null)level--;length--;return true;}public List<T> toArray(){List<T> o=new ArrayList<>();for(Node<T> n=head.next.get(0);n!=null;n=n.next.get(0))o.add(n.value);return o;}public Iterator<T> iterator(){return toArray().iterator();}}
}
